  <h2>Mortgage Calculator</h2>
  <div class="field">
    <div class="row"><span>Loan amount</span><span class="val" id="av">$300,000</span></div>
    <input type="range" id="amount" min="50000" max="1000000" step="5000" value="300000">
  </div>
  <div class="field">
    <div class="row"><span>Annual interest rate</span><span class="val" id="rv">5.5%</span></div>
    <input type="range" id="rate" min="1" max="15" step="0.1" value="5.5">
  </div>
  <div class="field">
    <div class="row"><span>Loan term (years)</span><span class="val" id="yv">30</span></div>
    <input type="range" id="years" min="5" max="40" step="1" value="30">
  </div>
  <div class="result">
    <div class="big" id="monthly">$0</div>
    <div class="muted" style="color:var(--m);font-size:13px;margin-bottom:10px">Estimated monthly payment</div>
    <div class="stat"><span class="lbl">Total paid</span><span id="totalPaid">$0</span></div>
    <div class="stat"><span class="lbl">Total interest</span><span id="totalInt">$0</span></div>
    <div class="stat"><span class="lbl">Number of payments</span><span id="numPayments">0</span></div>
