<script>
  var a=document.getElementById('amount'),r=document.getElementById('rate'),y=document.getElementById('years');
  function fmt(x){return '$'+Math.round(x).toLocaleString()}
  function calc(){
    var P=+a.value, rr=+r.value/100/12, n=+y.value*12;
    var M=rr>0? P*rr*Math.pow(1+rr,n)/(Math.pow(1+rr,n)-1) : P/n;
    document.getElementById('av').textContent=fmt(P);
    document.getElementById('rv').textContent=(+r.value).toFixed(1)+'%';
    document.getElementById('yv').textContent=y.value;
    document.getElementById('monthly').textContent=fmt(M);
    document.getElementById('totalPaid').textContent=fmt(M*n);
    document.getElementById('totalInt').textContent=fmt(M*n-P);
    document.getElementById('numPayments').textContent=n;
  }
  [a,r,y].forEach(function(e){e.oninput=calc});
  document.getElementById('reset').onclick=function(){a.value=300000;r.value=5.5;y.value=30;calc()};
  calc();
</script>
